const fmtDate = (date: string) => new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(date));
const scoreTone = (score: number) => score >= 80 ? 'text-primary' : score >= 60 ? 'text-accent-foreground' : 'text-destructive';
const scoreLabel = (score: number) => score >= 80 ? 'Strong signal' : score >= 60 ? 'Room to grow' : 'Needs attention';

function PageTitle({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div>{eyebrow && <div className="mb-2 font-mono text-[10px] font-medium uppercase tracking-[.18em] text-primary">{eyebrow}</div>}<h1 className="font-display text-3xl font-bold tracking-[-.045em] text-foreground md:text-[39px]">{title}</h1>{detail && <p className="mt-2 max-w-2xl text-[13px] leading-relaxed text-muted-foreground">{detail}</p>}</div>{action}</div>;
}

function ScoreRing({ score, size = 'lg', label = 'score' }: { score: number; size?: 'sm' | 'lg'; label?: string }) {
  const radius = size === 'lg' ? 47 : 28;
  const circumference = 2 * Math.PI * radius;
  const stroke = circumference * score / 100;
  return <div className={`relative shrink-0 ${size === 'lg' ? 'h-[132px] w-[132px]' : 'h-[76px] w-[76px]'}`} data-testid={`score-ring-${label}`}>
    <svg className="h-full w-full -rotate-90" viewBox="0 0 120 120"><circle cx="60" cy="60" r={radius} fill="none" stroke="hsl(var(--muted))" strokeWidth={size === 'lg' ? 8 : 7} /><circle cx="60" cy="60" r={radius} fill="none" stroke="hsl(var(--primary))" strokeLinecap="round" strokeWidth={size === 'lg' ? 8 : 7} strokeDasharray={`${stroke} ${circumference}`} /></svg>
    <div className="absolute inset-0 grid place-content-center text-center"><div className={`font-display font-bold tracking-[-.06em] ${size === 'lg' ? 'text-3xl' : 'text-lg'} ${scoreTone(score)}`}>{score}</div><div className="font-mono text-[8px] uppercase tracking-widest text-muted-foreground">{label}</div></div>
  </div>;
}

function ErrorState({ onRetry, message = 'We could not load this workspace.' }: { onRetry?: () => void; message?: string }) {
  return <div className="grid min-h-[320px] place-items-center rounded-2xl border border-destructive/20 bg-card p-8 text-center" data-testid="state-error"><CircleAlert className="mb-3 h-8 w-8 text-destructive" /><h2 className="font-display text-lg font-bold">A small detour</h2><p className="mt-1 max-w-sm text-sm text-muted-foreground">{message}</p>{onRetry && <button onClick={onRetry} className="mt-5 inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-xs font-bold text-primary-foreground" data-testid="button-retry"><RefreshCw className="h-3.5 w-3.5" /> Try again</button>}</div>;
}

function LoadingState({ rows = 3 }: { rows?: number }) {
  return <div className="space-y-3" data-testid="state-loading">{Array.from({ length: rows }).map((_, index) => <div key={index} className="h-[74px] animate-pulse rounded-2xl bg-muted" />)}</div>;
}

function EmptyState({ title, detail, href = '/analyze', action = 'Start an analysis', icon: Icon = FileText }: { title: string; detail: string; href?: string; action?: string; icon?: typeof FileText }) {
  return <div className="grid min-h-[280px] place-items-center rounded-2xl border border-dashed border-border bg-card p-8 text-center" data-testid="state-empty"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-muted text-primary"><Icon className="h-5 w-5" /></div><h2 className="mt-4 font-display text-lg font-bold">{title}</h2><p className="mt-1 max-w-sm text-sm leading-relaxed text-muted-foreground">{detail}</p><Link href={href} className="mt-5 inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground" data-testid="link-empty-action">{action}<ArrowRight className="h-3.5 w-3.5" /></Link></div>;
}

function StatCard({ label, value, detail, tone = 'default' }: { label: string; value: string | number; detail: string; tone?: 'default' | 'warm' | 'mint' }) {
  return <div className={`rounded-2xl border border-border bg-card p-5 shadow-sm ${tone === 'warm' ? 'border-accent/40 bg-accent/10' : tone === 'mint' ? 'border-primary/20 bg-primary/5' : ''}`} data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="mb-4 flex items-center justify-between"><span className="font-mono text-[9px] uppercase tracking-[.16em] text-muted-foreground">{label}</span><span className="h-2 w-2 rounded-full bg-primary" /></div><div className="font-display text-[32px] font-bold tracking-[-.06em]">{value}</div><div className="mt-1 text-[11px] text-muted-foreground">{detail}</div></div>;
}

